import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-transparent shadow-xs hover:bg-accent dark:bg-transparent dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Comp = asChild ? Slot : "button";

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

}

/**
 * The list endpoint types its rows as `Partial<ApiKey>` (server/supabase-adapter),
 * so every field can be absent. The prop type says so rather than asserting a
 * completeness the API does not promise, and the card degrades per-field: a row
 * with no id still renders, it just can't offer the actions that need one.
 */
function ApiKeyCard({ apiKey, onDelete, onRegenerate }: {
  apiKey: Partial<ApiKey>;
  onDelete: (id: number) => void;
  onRegenerate: (id: number) => void;
}) {
  const [showFull, setShowFull] = useState(false);
  const { id, keyPrefix } = apiKey;
  const displayKey = keyPrefix
    ? (showFull ? `${keyPrefix}${"•".repeat(32)}` : `${keyPrefix}••••••••`)
    : "—";

  return (
    <div className="flex items-center justify-between p-3 rounded-lg border border-border/50 bg-muted/20 hover:bg-muted/40 transition-colors">
      <div className="flex items-center gap-3 min-w-0">
        <Key className="h-4 w-4 text-muted-foreground shrink-0" />
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium truncate">{apiKey.name || "Unnamed key"}</span>
            <Badge variant={apiKey.isActive ? "default" : "secondary"} className="text-xs h-4">
              {apiKey.isActive ? "active" : "inactive"}
            </Badge>
          </div>
          <div className="flex items-center gap-2 mt-0.5">
            <code className="text-xs text-muted-foreground font-mono">{displayKey}</code>
            <button onClick={() => setShowFull(!showFull)} className="text-muted-foreground hover:text-foreground">
              {showFull ? <EyeOff className="h-3 w-3" /> : <Eye className="h-3 w-3" />}
            </button>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">
            {apiKey.createdAt && `Created ${new Date(apiKey.createdAt).toLocaleDateString()}`}
            {apiKey.lastUsedAt && ` · Last used ${new Date(apiKey.lastUsedAt).toLocaleDateString()}`}
          </p>
        </div>
      </div>
      <div className="flex items-center gap-1 shrink-0">
        <Button
          variant="ghost" size="icon" className="h-7 w-7"
          disabled={!keyPrefix}
          onClick={() => { if (keyPrefix) { navigator.clipboard.writeText(keyPrefix); toast.success("Key prefix copied"); } }}
        >
          <Copy className="h-3.5 w-3.5" />
        </Button>
        <Button
          variant="ghost" size="icon" className="h-7 w-7"
          disabled={id === undefined}
          onClick={() => { if (id !== undefined) onRegenerate(id); }}
        >
          <RefreshCw className="h-3.5 w-3.5" />
        </Button>
        <Button
          variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive"
          disabled={id === undefined}
          onClick={() => { if (id !== undefined) onDelete(id); }}
        >
          <Trash2 className="h-3.5 w-3.5" />
        </Button>
      </div>

