1	#!/usr/bin/env node
2	// Stop-event adapter: decide whether this turn may end.
3	//
4	// Exit 0 = allow the stop. Exit 2 = REFUSE, with stderr shown to the model.
5	// It shares ONE ruleset with the audit path (concession-gate.mjs); there is no
6	// second copy of the stopping rule that could drift from the first.
7	import fs from "node:fs";
8	import { isConcession } from "./concession-gate.mjs";
9	import { enumerateCapability } from "./capability-map.mjs";
10	import { continuationDecision, TERMINAL_CONDITIONS as TERMINAL } from "./continuation.mjs";
11	
12	let ev = {};
13	try { ev = JSON.parse(fs.readFileSync(0, "utf8")); } catch { process.exit(0); }
14	
15	// A recorded exhaustion artifact for THIS turn is what satisfies the gate.
16	const EVIDENCE = `${process.env.CLAUDE_PROJECT_DIR || "."}/build-os/motion/exhaustion/current.json`;
17	
18	let lastAssistant = "";
19	try {
20	  const lines = fs.readFileSync(ev.transcript_path, "utf8").split("\n").filter(Boolean);
21	  for (let i = lines.length - 1; i >= 0; i--) {
22	    const m = JSON.parse(lines[i]);
23	    if (m?.message?.role === "assistant") {
24	      lastAssistant = (m.message.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n");
25	      break;
26	    }
27	  }
28	} catch { process.exit(0); }
29	
30	// CONTINUATION IS CHECKED FIRST, and it applies whether or not the turn
31	// concedes. The observed defect was a turn that conceded NOTHING - it simply
32	// finished a task and stopped - so a stop gate that only inspects concessions
33	// would have allowed it.
34	try {
35	  const q = JSON.parse(fs.readFileSync(`${process.env.CLAUDE_PROJECT_DIR || "."}/build-os/motion/queue.json`, "utf8"));
36	  const cont = continuationDecision(q);
37	  if (cont.decision === "continue") {
38	    process.stderr.write(
39	`STOP REFUSED — the queue still holds runnable work.
40	
41	Finishing a task is NOT a stop condition, and neither is a commit awaiting a push grant:
42	execution authority and publication authority are different. An unpushed commit blocks
43	publication, not work.
44	
45	NEXT RUNNABLE TASK: #${cont.next_task}${cont.next_subject ? " — " + cont.next_subject : ""}
46	${cont.reasons.map((r) => "  - " + r).join("\n")}
47	
48	Begin it now. Do not stop for a narrative recap.
49	
50	Stopping requires one of: ${TERMINAL.join(", ")}.
51	`);
52	    process.exit(2);
53	  }
54	} catch { /* no queue file: fall through to the concession check */ }
55	
56	const { conceding } = isConcession(lastAssistant);
57	if (!conceding) process.exit(0);
58	
59	let evidence = null;
60	try { evidence = JSON.parse(fs.readFileSync(EVIDENCE, "utf8")); } catch {}
61	// Evidence must be for THIS conclusion, not a stale artifact from an earlier one.
62	const fresh = evidence && evidence.for_conclusion &&
63	  lastAssistant.toLowerCase().includes(String(evidence.for_conclusion).toLowerCase().slice(0, 40));
64	
65	if (fresh && evidence.verdict === "concession_allowed") process.exit(0);
66	
67	const cap = enumerateCapability(evidence?.capability || "operator_lab_write", "claude");
68	process.stderr.write(
69	`CONCESSION BLOCKED — this turn concedes (blocked / cannot / pause / needs-manual) without recorded capability-exhaustion evidence.
70	
